from pathlib import Path

def replace_between(text,start,end,repl):
    a=text.find(start)
    if a<0: raise SystemExit('Missing start marker: '+start)
    b=text.find(end,a)
    if b<0: raise SystemExit('Missing end marker: '+end)
    return text[:a]+repl+text[b:]

